const n={ocnal:{baipishu:"Sách trắng",home1:"Mở khóa thế giới tiền điện tử",home2:"Nạp tiền ngay",home3:"Tên",home4:"Giá",home5:"Thay đổi 24h",home6:"Giao dịch",home7:"Bắt đầu",home8:"Tạo tài khoản",home9:"Đăng ký tài khoản để tận hưởng nhiều đặc quyền và dịch vụ hơn",home10:"Đăng ký",home11:"Nạp tiền",home12:"Nạp tiền vào tài khoản và bắt đầu đầu tư tiền điện tử",home13:"Nạp tiền điện tử",home14:"Bắt đầu giao dịch",home15:"Bán, mua hoặc sao chép giao dịch, khám phá thêm",home16:"Khám phá thị trường",home17:"Thị trường tiền điện tử đang bùng nổ, bao gồm tiền kỹ thuật số, công nghệ blockchain và nhiều lĩnh vực khác. Triển vọng rất hứa hẹn, nhưng đầu tư cần thận trọng.",home18:"Giao ngay",home19:"Giao dịch theo thời gian thực trên thị trường giao ngay với biến động giá nhanh.",home20:"Hợp đồng vĩnh cửu",home21:"Giao dịch hợp đồng cung cấp đòn bẩy, có thể đạt lợi nhuận cao.",home22:"Quyền chọn",home23:"Giao dịch quyền chọn cung cấp chiến lược phòng hộ linh hoạt để kiểm soát rủi ro và tạo lợi nhuận.",home24:"Tài chính",home25:"Lập kế hoạch tự tin. Đầu tư thông minh. Ít lo lắng hơn",home26:"Lợi suất thường niên cao nhất trong lịch sử",home27:"Hiện tại",home28:"Định kỳ",home29:"Mua ngay",home30:"Ai cũng có thể sử dụng tiền điện tử",home31:"Từ trải nghiệm ban đầu với giao dịch tiền điện tử đến lần mua sản phẩm tài chính đầu tiên, nền tảng sẽ giúp bạn dễ dàng kiếm coin",home32:"Tìm hiểu về tiền điện tử",home33:"Tìm hiểu tất cả về tiền điện tử để bắt đầu đầu tư",home34:"Câu hỏi thường gặp",home35:"Sẵn sàng bắt đầu hành trình crypto của bạn?",home36:"Sàn giao dịch tiền điện tử là gì?",home37:"Sàn giao dịch tiền điện tử là thị trường số cho phép người dùng mua và bán các loại tiền điện tử như Bitcoin, Ethereum và Tether. Sàn Binance là sàn giao dịch crypto lớn nhất theo khối lượng giao dịch.",home38:"Nền tảng cung cấp những sản phẩm nào?",home39:"Là nền tảng giao dịch tiền điện tử hàng đầu toàn cầu, hiện nền tảng phục vụ hơn 150 triệu người dùng đã đăng ký tại hơn 180 quốc gia/khu vực. Với phí giao dịch thấp, nền tảng cung cấp hơn 350 loại tiền điện tử có thể giao dịch, trở thành lựa chọn ưu tiên để giao dịch Bitcoin, altcoin và các tài sản số khác. <br><br> Trên nền tảng, người dùng có thể: <br><br>1.Giao dịch hàng trăm loại tiền điện tử và cặp giao dịch.<br><br>2.Mua và bán tiền điện tử thông qua giao dịch giao ngay của nền tảng.<br><br>3.Kiếm lãi tiền điện tử thông qua các sản phẩm quản lý tài sản của nền tảng",home40:"Cách giao dịch tiền điện tử trên nền tảng",home41:"Trên nền tảng, bạn có thể giao dịch hàng trăm loại tiền điện tử ở thị trường giao ngay, hợp đồng tương lai và quyền chọn. Để bắt đầu giao dịch, người dùng cần đăng ký tài khoản, hoàn tất xác minh danh tính và nạp/mua tiền điện tử, sau đó có thể bắt đầu giao dịch.",home42:"Nền tảng này có phải là sàn giao dịch tiền điện tử an toàn không?",home43:"Nền tảng cam kết cung cấp môi trường giao dịch an toàn và đáng tin cậy. Chúng tôi sở hữu một trong những công nghệ bảo mật tiên tiến nhất và đội ngũ vận hành hàng đầu thế giới, bao gồm đội ngũ bảo mật chuyên trách luôn hoạt động để đảm bảo an toàn cho tài sản và tài khoản của bạn. Chúng tôi cũng đã trải qua quá trình xác minh dự trữ độc lập để xác nhận rằng toàn bộ tài sản người dùng được bảo chứng theo tỷ lệ 1:1.",home44:"Làm thế nào để xử lý khi quên mật khẩu đăng nhập?",home45:"Bạn có thể nhấp vào 'Quên mật khẩu' trên trang đăng nhập và đặt lại 'Mật khẩu đăng nhập'.",home46:"Tại sao cần xác thực danh tính?",home47:"Để đảm bảo an toàn cho nguồn tiền của bạn và ngăn chặn các hoạt động rửa tiền, chúng tôi cần đảm bảo tài khoản nhận tiền của bạn gắn liền với thông tin danh tính của tài khoản hiện tại.",home48:"Thị trường",home49:"Thị trường giao dịch tiền điện tử toàn cầu hỗ trợ giao dịch đa tiền tệ, vừa an toàn vừa hiệu quả.",home50:"Tài khoản của tôi",home51:"Nạp tiền",home52:"Rút tiền",home53:"Chuyển đổi",home54:"Nổi bật",home55:"Đầu tư vào token mới phát hành và khai thác tiềm năng lợi nhuận cao",home56:"Tin tức",home57:"Vì sao chọn chúng tôi?",home58:"Được hàng triệu người tin dùng",home59:"Số lượng người dùng",home60:"Đơn vị đối tác",home61:"Phí giao dịch tối thiểu",home62:"Đối tác",home63:"Khối lượng 24h"}};export{n as default};
